
-- Handbook v1.14 remediation: make every feed item a distinct, scoped notification.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'officialEnglish text' WHEN 1 THEN 'English textaccountEnglish textreminder' WHEN 2 THEN 'English text'
      WHEN 3 THEN 'English textpleaseportalEnglish text' WHEN 4 THEN 'English textreportcancheckview' WHEN 5 THEN 'English text'
      WHEN 6 THEN 'clientEnglish textlocationupdate' WHEN 7 THEN 'English texttimechange' WHEN 8 THEN 'studydayEnglish text'
      WHEN 9 THEN 'English textnotification' WHEN 10 THEN 'English textnewEnglish text' WHEN 11 THEN 'English textbudgetEnglish text'
      WHEN 12 THEN 'countEnglish textupdate' WHEN 13 THEN 'English text' WHEN 14 THEN 'English textcheckreminder'
      WHEN 15 THEN 'programEnglish text' ELSE 'English text' END AS event_fact,
    CASE rowid % 19
      WHEN 0 THEN 'noneEnglish text' WHEN 1 THEN 'onlyEnglish text' WHEN 2 THEN 'andEnglish textstatusnoneEnglish text'
      WHEN 3 THEN 'canatEnglish texttimeEnglish text' WHEN 4 THEN 'notEnglish textplease' WHEN 5 THEN 'English textfirstcheckEnglish textrecord'
      WHEN 6 THEN 'retainEnglish text' WHEN 7 THEN 'notEnglish textpayment' WHEN 8 THEN 'English texthasEnglish textdayEnglish text'
      WHEN 9 THEN 'notEnglish textscoreEnglish text' WHEN 10 THEN 'English textaccount' WHEN 11 THEN 'needEnglish texttime zone'
      WHEN 12 THEN 'English textnotcanexternal sharing' WHEN 13 THEN 'historicalversionEnglish textcanEnglish text' WHEN 14 THEN 'statusmayEnglish textafterupdate'
      WHEN 15 THEN 'notneedEnglish text' WHEN 16 THEN 'onlyrecordrisk，notEnglish text' WHEN 17 THEN 'English textaftercanEnglish textread'
      ELSE 'useofficialsubsequentnotificationas authority' END AS scope_fact
  FROM notifications WHERE notification_id LIKE 'notif_background_examprep_%'
)
UPDATE notifications
SET title = (SELECT event_fact FROM facts WHERE facts.rid=notifications.rowid),
    body = CASE rowid % 5
      WHEN 0 THEN (SELECT event_fact || '；' || scope_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 1 THEN (SELECT 'English textupdate：' || event_fact || '。English textdescription：' || scope_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 2 THEN (SELECT scope_fact || '；English textitemrecordEnglish text' || event_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 3 THEN (SELECT 'English text' || event_fact || '，English textas' || scope_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
      ELSE (SELECT event_fact || 'alreadyenteredEnglish textinEnglish text。' || scope_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
    END,
    notification_id = replace(notification_id, 'notif_background_examprep_', 'notif_context_examprep_')
WHERE notification_id LIKE 'notif_background_examprep_%';

UPDATE notifications
SET payload_json = json_object('record_kind','context_update','actionable',0,'source',source)
WHERE notification_id LIKE 'notif_context_examprep_%';
